suppressPackageStartupMessages({library(data.table);library(GenomicRanges);library(GenomicAlignments)})
p='output/followup_analysis/';set.seed(260926)
s=fread(paste0(p,'tables/summit_normalized_positions.tsv.gz'));d=fread(paste0(p,'raw_count_quantile/continuous_delta_delta_peaks.tsv'));s=merge(s,d[,.(peak_id,delta_delta)],by='peak_id');s[,preference:=ifelse(delta_delta>0,'324','328')];s[,zone:=ifelse(fraction<.1,'first10',ifelse(fraction>=.9,'last10','middle80'))];st=list()
for(k in c('intron','3UTR'))for(q in 0:4){z=s[kind==k];if(q>0)z=z[quartile==q];for(b in c('first10','last10')){z[,boundary:=zone==b];tt=table(factor(z$preference,levels=c('324','328')),factor(z$boundary,levels=c(TRUE,FALSE)));ft=fisher.test(tt);st[[paste(k,q,b)]]=data.table(kind=k,quartile=q,boundary=b,n324=sum(tt[1,]),n328=sum(tt[2,]),boundary324=tt[1,1],boundary328=tt[2,1],odds_ratio_324_boundary=unname(ft$estimate),p=ft$p.value)}}
st=rbindlist(st);st[,q_BH:=p.adjust(p,'BH')];fwrite(st,paste0(p,'tables/construct_boundary_tests.tsv'),sep='\t')
x=readRDS(paste0(p,'cache/resampling_arrays.rds'));support=rbindlist(lapply(1:51,function(it)data.table(sample_id=x$meta$sample_id,iteration=it-1,nonzero_peaks=colSums(x$counts[,,it]>0),universe=16046)));support[,fraction_supported:=nonzero_peaks/universe];fwrite(support,paste0(p,'tables/downsampling_support_iterations.tsv'),sep='\t')
w=fread(paste0(p,'tables/spatial_components_and_delta_iterations.tsv.gz'));w=w[grepl('metaintron',profile)];w[,zone:=ifelse(bin<10,'first10',ifelse(bin>=90,'last10','middle80'))];z=w[,.(delta=mean(dd)),by=.(profile,iteration,zone)];z=dcast(z,profile+iteration~zone,value.var='delta');z[,`:=`(first_minus_middle=first10-middle80,last_minus_middle=last10-middle80)];fwrite(z,paste0(p,'tables/spatial_construct_boundary_iterations.tsv'),sep='\t')
# Actual full-depth intron support in each inward bin, reconstructed from aligned blocks.
f=fread(paste0(p,'tables/eligible_introns.tsv.gz'))[length_nt>=2000];fg=GRanges(f$chrom,IRanges(f$start+1,f$end),f$strand);res=list()
for(sid in x$meta$sample_id){message('Inward support ',sid);a=fread(paste0('data/results_round2/',sid,'/read_annotations.tsv.gz'),select=c('chrom','position_1based','strand','cigar'));bl=cigarRangesAlongReferenceSpace(a$cigar,pos=a$position_1based,ops=c('M','=','X'),reduce.ranges=TRUE);ri=rep(seq_len(nrow(a)),lengths(bl));bg=GRanges(a$chrom[ri],unlist(bl),a$strand[ri]);h=suppressWarnings(findOverlaps(bg,fg));bi=queryHits(h);fi=subjectHits(h);lo=pmax(start(bg)[bi]-1,f$start[fi]);hi=pmin(end(bg)[bi],f$end[fi]);aa=ifelse(f$strand[fi]=='-',f$end[fi]-hi,lo-f$start[fi]);bb=ifelse(f$strand[fi]=='-',f$end[fi]-lo,hi-f$start[fi]);for(side in c('donor','acceptor')){a=if(side=='donor')aa else f$length_nt[fi]-bb;b=if(side=='donor')bb else f$length_nt[fi]-aa;ok=a<1000 & b>0;a=pmax(0,a[ok]);b=pmin(1000,b[ok]);ffi=fi[ok];l=floor(a/10);u=ceiling(b/10)-1;nn=u-l+1;ix=rep(seq_along(nn),nn);bins=rep(l,nn)+sequence(nn)-1;dt=unique(data.table(feature=ffi[ix],bin=bins));z=dt[,.(nonzero_introns=.N),by=bin];z=merge(data.table(bin=0:99),z,all.x=TRUE);z[is.na(nonzero_introns),nonzero_introns:=0L];z[,`:=`(side=side,sample_id=sid,eligible_introns=nrow(f),fraction_supported=nonzero_introns/nrow(f))];res[[paste(sid,side)]]=z}}
fwrite(rbindlist(res),paste0(p,'tables/inward_nonzero_bin_support.tsv'),sep='\t')
